    internal static int PcLex(emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs) {
        // Read tokens until one is an operand or an operator: 0 at the end of the
        // stream, 1 when an operand was pushed, 2 when an operator was read (its code,
        // up to three characters, the first in the low byte, is in C_OP).
        int end = emon.Port.CellsAt(cx, CEnd);
        int p = PcSkip(cs, emon.Port.CellsAt(cx, CPos), end);
        int tok = 0;
        while ((p < end) && (tok == 0)) {
            p = PcLexOne(cx, ox, cs, p, end);
            tok = emon.Port.CellsAt(cx, CTok);
            if (tok == 0) {
                p = PcSkip(cs, p, end);
            }
        }
        emon.Port.CellsSet(cx, CPos, p);
        return tok;
    }
    public static int PcInit(emon.Port.Cells cx, emon.Port.Cells ox) {
        // Empty the interpreter for a new document: zeroed cells, no fonts known.
        int i = 0;
        emon.Port.CellsDrop(cx, 0);
        while (i < CSize) {
            emon.Port.CellsPush(cx, 0);
            i += 1;
        }
        emon.Port.CellsDrop(ox, 0);
        i = 0;
        while (i < OxBase) {
            emon.Port.CellsPush(ox, 0);
            i += 1;
        }
        emon.Port.CellsSet(cx, COplim, emon.Port.LimitOf(5));
        emon.Port.CellsSet(cx, CFlim, emon.Port.LimitOf(6));
        emon.Port.CellsSet(cx, CFidlim, emon.Port.LimitOf(14));
        emon.Port.CellsSet(cx, CMctop, -1);
        return 0;
    }
    internal static int PcGsReset(emon.Port.Cells cx) {
        // The initial graphics state: the base matrix, black, opaque, no font.
        Fx.MxCopy(cx, CCur + GCtm, CBase);
        Fx.FxPut(cx, CCur + GTc, (long) 0);
        Fx.FxPut(cx, CCur + GTw, (long) 0);
        Fx.FxPut(cx, CCur + GTh, Fx.FxOne());
        Fx.FxPut(cx, CCur + GTl, (long) 0);
        Fx.FxPut(cx, CCur + GRise, (long) 0);
        Fx.FxPut(cx, CCur + GFs, (long) 0);
        emon.Port.CellsSet(cx, CCur + GMode, 0);
        emon.Port.CellsSet(cx, CCur + GFont, 0);
        emon.Port.CellsSet(cx, CCur + GColor, 0);
        emon.Port.CellsSet(cx, CCur + GAlpha, 1000);
        emon.Port.CellsSet(cx, CCur + GFam, 1);
        emon.Port.CellsSet(cx, CCur + GScolor, 0);
        emon.Port.CellsSet(cx, CCur + GSalpha, 1000);
        emon.Port.CellsSet(cx, CCur + GFcs, -1);
        emon.Port.CellsSet(cx, CCur + GScs, -1);
        emon.Port.CellsSet(cx, CCur + GSfam, 1);
        emon.Port.CellsSet(cx, CCur + GClip, -1);
        emon.Port.CellsSet(cx, CCur + GBm, 0);
        emon.Port.CellsSet(cx, CCur + GSmask, 0);
        Fx.FxPut(cx, CCur + GLw, Fx.FxOne());
        emon.Port.CellsSet(cx, CCur + GDash, 0);
        return 0;
    }
    internal static int PcBaseMatrix(emon.Port.Cells cx, int x0, int y0, int x1, int y1, int rot) {
        // The matrix from user space (points) to page space (centipoints, y down,
        // the crop box's corner at the origin, /Rotate applied). x0..y1 are the crop
        // box in centipoints.
        long h = (long) 1677721600;
        long nh = (long) -1677721600;
        if (rot == 90) {
            Fx.MxSet(cx, CBase, (long) 0, h, h, (long) 0, Fx.FxOfInt(0 - y0), Fx.FxOfInt(0 - x0));
        }
        if (rot == 180) {
            Fx.MxSet(cx, CBase, nh, (long) 0, (long) 0, h, Fx.FxOfInt(x1), Fx.FxOfInt(0 - y0));
        }
        if (rot == 270) {
            Fx.MxSet(cx, CBase, (long) 0, nh, nh, (long) 0, Fx.FxOfInt(y1), Fx.FxOfInt(x1));
        }
        if ((rot != 90) && ((rot != 180) && (rot != 270))) {
            Fx.MxSet(cx, CBase, h, (long) 0, (long) 0, nh, Fx.FxOfInt(0 - x0), Fx.FxOfInt(y1));
        }
        return 0;
    }
    internal static int PcSave(emon.Port.Cells cx) {
        int d = emon.Port.CellsAt(cx, CDepth);
        if (d >= MaxGs) {
            PcWarnSet(cx, WStates);
            return 0;
        }
        PcCopyCells(cx, CStack + (d * GsStride), CCur, GsStride);
        emon.Port.CellsSet(cx, CDepth, d + 1);
        return 1;
    }
    internal static int PcRestore(emon.Port.Cells cx) {
        // Q: pops only what this stream pushed.
        int d = emon.Port.CellsAt(cx, CDepth);
        int @base = emon.Port.CellsAt(cx, CGsbase);
        if (d <= @base) {
            PcWarnSet(cx, WStates);
            return 0;
        }
        PcCopyCells(cx, CCur, CStack + ((d - 1) * GsStride), GsStride);
        emon.Port.CellsSet(cx, CDepth, d - 1);
        return 1;
    }
    internal static int PcUpdateM(emon.Port.Cells cx) {
        // M = Tm x CTM, the matrix from text space to page space.
        Fx.MxMul(cx, CM, CTm, CCur + GCtm);
        return 0;
    }
    internal static int PcAdvance(emon.Port.Cells cx, long dx, long dy) {
        // Move the text position by (dx, dy) in TEXT space: Tm and M both translate
        // by the vector through their own linear parts.
        long ta = Fx.FxGet(cx, CTm);
        long tb = Fx.FxGet(cx, CTm + 2);
        long tc = Fx.FxGet(cx, CTm + 4);
        long td = Fx.FxGet(cx, CTm + 6);
        long te = Fx.FxGet(cx, CTm + 8);
        long tf = Fx.FxGet(cx, CTm + 10);
        long ma = Fx.FxGet(cx, CM);
        long mb = Fx.FxGet(cx, CM + 2);
        long mc = Fx.FxGet(cx, CM + 4);
        long md = Fx.FxGet(cx, CM + 6);
        long me = Fx.FxGet(cx, CM + 8);
        long mf = Fx.FxGet(cx, CM + 10);
        Fx.FxPut(cx, CTm + 8, Fx.FxClamp(unchecked(te + unchecked(Fx.FxMul(dx, ta) + Fx.FxMul(dy, tc)))));
        Fx.FxPut(cx, CTm + 10, Fx.FxClamp(unchecked(tf + unchecked(Fx.FxMul(dx, tb) + Fx.FxMul(dy, td)))));
        Fx.FxPut(cx, CM + 8, Fx.FxClamp(unchecked(me + unchecked(Fx.FxMul(dx, ma) + Fx.FxMul(dy, mc)))));
        Fx.FxPut(cx, CM + 10, Fx.FxClamp(unchecked(mf + unchecked(Fx.FxMul(dx, mb) + Fx.FxMul(dy, md)))));
        return 0;
    }
    internal static int PcTd(emon.Port.Cells cx, long tx, long ty) {
        // Td: the line matrix moves by (tx, ty) in its own space; the text matrix
        // starts over there.
        Fx.MxTranslate(cx, CTmp, tx, ty);
        Fx.MxMul(cx, CTlm, CTmp, CTlm);
        Fx.MxCopy(cx, CTm, CTlm);
        return 0;
    }
    internal static int PcSetTm(emon.Port.Cells cx, long a, long b, long c, long d, long e, long f) {
        Fx.MxSet(cx, CTm, a, b, c, d, e, f);
        Fx.MxCopy(cx, CTlm, CTm);
        return 0;
    }
    internal static int PcNextLine(emon.Port.Cells cx) {
        // T*: down by the leading.
        long tl = Fx.FxGet(cx, CCur + GTl);
        PcTd(cx, (long) 0, ((long) 0) - tl);
        return 0;
    }
    internal static int PcByte(long v) {
        // A colour component in 0..1 (an Fx) as 0..255, rounded.
        int n = Fx.FxRound(Fx.FxMul(v, Fx.FxOfInt(255)));
        if (n < 0) {
            return 0;
        }
        if (n > 255) {
            return 255;
        }
        return n;
    }
    internal static int PcRgb(int r, int g, int bl) {
        return (r * 65536) + ((g * 256) + bl);
    }
    internal static int PcDictLookup(emon.Port.Cells ar, int dict, emon.Port.Cells ox, int ns, int nl) {
        // The value (unresolved) under the key spelled ox[ns, ns+nl), or 0. The
        // last of a repeated key wins.
        int k = Pdflex.PlFirst(ar, dict);
        int v = 0;
        int found = 0;
        int same = 0;
        int i = 0;
        if (Pdflex.PlKindOf(ar, dict) != 7) {
            return 0;
        }
        while (k != 0) {
            v = Pdflex.PlNext(ar, k);
            if ((Pdflex.PlKindOf(ar, k) == 4) && (Pdflex.PlNameLen(ar, k) == nl)) {
                same = 1;
                i = 0;
                while ((same == 1) && (i < nl)) {
                    if (Pdflex.PlNameByte(ar, k, i) != emon.Port.CellsAt(ox, ns + i)) {
                        same = 0;
                    }
                    i += 1;
                }
                if (same == 1) {
                    found = v;
                }
            }
            if (v == 0) {
                k = 0;
            } else {
                k = Pdflex.PlNext(ar, v);
            }
        }
        return found;
    }
    internal static int PcResEntry(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, int kindId, int ei) {
        // The UNRESOLVED entry named by operand ei (a name) in the current Resources'
        // sub-dictionary `kind-id` (`(pn-font)`, `(pn-x-object)`, ...), 0 when none.
        int res = emon.Port.CellsAt(cx, CRes);
        int ns = PcEa(ox, ei);
        int nl = PcEb(ox, ei);
        if (res == 0) {
            return 0;
        }
        int sub = Pdfdoc.PdDget(src, ar, dc, a, b, st, res, kindId);
        if (sub == 0) {
            return 0;
        }
        return PcDictLookup(ar, sub, ox, ns, nl);
    }
    internal static int PcFLoad(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int fh) {
        if (slot == 0) {
            return Pdffont.PfnLoad(src, ar, dc, a, b, st, f0, @out, fh);
        }
        if (slot == 1) {
            return Pdffont.PfnLoad(src, ar, dc, a, b, st, f1, @out, fh);
        }
        if (slot == 2) {
            return Pdffont.PfnLoad(src, ar, dc, a, b, st, f2, @out, fh);
        }
        return Pdffont.PfnLoad(src, ar, dc, a, b, st, f3, @out, fh);
    }
    internal static int PcFQ(emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int which) {
        // A font's metric: which 0 ascent, 1 descent, 2 vertical, 3 DW2 v, 4 DW2 w.
        if (slot == 0) {
            if (which == 0) {
                return Pdffont.PfnAscent(f0);
            }
            if (which == 1) {
                return Pdffont.PfnDescent(f0);
            }
            if (which == 2) {
                return Pdffont.PfnVertical(f0);
            }
            if (which == 3) {
                return Pdffont.PfnDw2V(f0);
            }
            return Pdffont.PfnDw2W(f0);
        }
        if (slot == 1) {
            if (which == 0) {
                return Pdffont.PfnAscent(f1);
            }
            if (which == 1) {
                return Pdffont.PfnDescent(f1);
            }
            if (which == 2) {
                return Pdffont.PfnVertical(f1);
            }
            if (which == 3) {
                return Pdffont.PfnDw2V(f1);
            }
            return Pdffont.PfnDw2W(f1);
        }
        if (slot == 2) {
            if (which == 0) {
                return Pdffont.PfnAscent(f2);
            }
            if (which == 1) {
                return Pdffont.PfnDescent(f2);
            }
            if (which == 2) {
                return Pdffont.PfnVertical(f2);
            }
            if (which == 3) {
                return Pdffont.PfnDw2V(f2);
            }
            return Pdffont.PfnDw2W(f2);
        }
        if (which == 0) {
            return Pdffont.PfnAscent(f3);
        }
        if (which == 1) {
            return Pdffont.PfnDescent(f3);
        }
        if (which == 2) {
            return Pdffont.PfnVertical(f3);
        }
        if (which == 3) {
            return Pdffont.PfnDw2V(f3);
        }
        return Pdffont.PfnDw2W(f3);
    }
    internal static int PcFCodeLen(emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int b0, int b1, int b2, int b3) {
        if (slot == 0) {
