            emon.Port.CellsSet(cx, at + SAsc, 0);
            emon.Port.CellsSet(cx, at + SDesc, 0);
            emon.Port.CellsSet(cx, at + SVert, 0);
        }
        emon.Port.CellsSet(cx, CSlot, pick);
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(cx, CAbort, 1);
        }
        return 0;
    }
    internal static int PcTf(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, int n) {
        // Tf: the font named by operand 0 from the current Resources, at the size of
        // operand 1. The dictionary is resolved here and loaded at the first glyph.
        long size = PcNum(ox, n, 1);
        int fh = 0;
        int raw = 0;
        Fx.FxPut(cx, CCur + GFs, size);
        if ((n >= 1) && (PcKind(ox, 0) == KName)) {
            raw = PcResEntry(src, ar, dc, a, b, st, cx, ox, Pdfnames.PnFont(), 0);
            if (raw != 0) {
                fh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, raw);
            }
        }
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(cx, CAbort, 1);
            return 0;
        }
        if (fh == 0) {
            PcWarnSet(cx, WFont);
        } else if (Pdflex.PlKindOf(ar, fh) != 7) {
            fh = 0;
            PcWarnSet(cx, WFont);
        }
        emon.Port.CellsSet(cx, CCur + GFont, fh);
        emon.Port.CellsSet(cx, CCur + GFobj, 0);
        if ((fh != 0) && (raw != 0)) {
            if (Pdflex.PlKindOf(ar, raw) == 9) {
                emon.Port.CellsSet(cx, CCur + GFobj, Pdflex.PlIntValue(ar, raw));
            }
        }
        return 0;
    }
    internal static long PcMin4(long p, long q, long r, long s) {
        long m = p;
        if (q < m) {
            m = q;
        }
        if (r < m) {
            m = r;
        }
        if (s < m) {
            m = s;
        }
        return m;
    }
    internal static long PcMax4(long p, long q, long r, long s) {
        long m = p;
        if (q > m) {
            m = q;
        }
        if (r > m) {
            m = r;
        }
        if (s > m) {
            m = s;
        }
        return m;
    }
    internal static int PcDirAngle(long a, long b) {
        // The angle of the direction (a, b) in page space (y down), by `ev-angle`: halve both until the
        // larger fits 30 bits, so the angle of a matrix axis in 24-bit fixed point keeps all its precision.
        long x = a;
        long y = b;
        long m = (long) 0;
        if (x < ((long) 0)) {
            m = ((long) 0) - x;
        } else {
            m = x;
        }
        if (y < ((long) 0)) {
            if ((((long) 0) - y) > m) {
                m = ((long) 0) - y;
            }
        } else if (y > m) {
            m = y;
        }
        while (m > ((long) 1073741824)) {
            x = x / ((long) 2);
            y = y / ((long) 2);
            m = m / ((long) 2);
        }
        return Evidence.EvAngle((int) x, (int) y);
    }
    public static int PcPua(int cp) {
        // D1625: the private-use code points of Adobe's Symbol font (U+F8E5..U+F8FE), which TeX's glyph-to-Unicode lists give the
        // big brackets, braces and parentheses and the extension pieces of a tall delimiter (CMEX10), are the characters Unicode
        // later gave them (U+239B..U+23AF, U+23D0, the serif signs). Every other code point is itself.
        if ((cp < 63717) || (cp > 63742)) {
            return cp;
        }
        if (cp == 63717) {
            return 9135;
        }
        if (cp == 63718) {
            return 9168;
        }
        if (cp == 63719) {
            return 9135;
        }
        if (cp == 63720) {
            return 174;
        }
        if (cp == 63721) {
            return 169;
        }
        if (cp == 63722) {
            return 8482;
        }
        if (cp <= 63725) {
            return 9115 + (cp - 63723);
        }
        if (cp <= 63728) {
            return 9121 + (cp - 63726);
        }
        if (cp <= 63731) {
            return 9127 + (cp - 63729);
        }
        if (cp == 63732) {
            return 9130;
        }
        if (cp == 63733) {
            return 9134;
        }
        if (cp <= 63736) {
            return 9118 + (cp - 63734);
        }
        if (cp <= 63739) {
            return 9124 + (cp - 63737);
        }
        return 9131 + (cp - 63740);
    }
    internal static int PcGlyph(emon.Port.Cells cx, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int code, int ncode) {
