        long p1x = Fx.MxX(cx, CM, x1t, y0t);
        long p1y = Fx.MxY(cx, CM, x1t, y0t);
        long p2x = Fx.MxX(cx, CM, x0t, y1t);
        long p2y = Fx.MxY(cx, CM, x0t, y1t);
        long p3x = Fx.MxX(cx, CM, x1t, y1t);
