        Evidence.GlSet(gl, g, Evidence.GfFalpha(), emon.Port.CellsAt(cx, CCur + GAlpha));
        Evidence.GlSet(gl, g, Evidence.GfStroke(), emon.Port.CellsAt(cx, CCur + GScolor));
