    }
    internal static int PcShowStr(emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int s) {
