        int ln = PcEb(ox, s);
        int slot = emon.Port.CellsAt(cx, CSlot);
        int okfont = 0;
        int i = 0;
        int n = 1;
        int code = 0;
        int k = 0;
        int b0 = 0;
        int b1 = -1;
        int b2 = -1;
        int b3 = -1;
        if (slot >= 0) {
            if (emon.Port.CellsAt(cx, (CSlots + (slot * SlotStride)) + SStatus) == 0) {
                okfont = 1;
            }
        }
        while (i < ln) {
            b0 = emon.Port.CellsAt(ox, start + i);
            b1 = -1;
            b2 = -1;
            b3 = -1;
            if ((i + 1) < ln) {
                b1 = emon.Port.CellsAt(ox, start + (i + 1));
            }
            if ((i + 2) < ln) {
                b2 = emon.Port.CellsAt(ox, start + (i + 2));
            }
            if ((i + 3) < ln) {
                b3 = emon.Port.CellsAt(ox, start + (i + 3));
            }
