    }
    internal static int PcShowArr(emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int s) {
        // TJ: strings and adjustments. An adjustment n moves the position by
        // -n/1000 of the font size (along x, scaled by Th; along y in vertical mode).
        int cnt = PcEa(ox, s);
        int slot = emon.Port.CellsAt(cx, CSlot);
        long fs = Fx.FxGet(cx, CCur + GFs);
        long th = Fx.FxGet(cx, CCur + GTh);
        int vert = 0;
        int j = s + 1;
        int k = 0;
        long delta = (long) 0;
        if (slot >= 0) {
            vert = emon.Port.CellsAt(cx, (CSlots + (slot * SlotStride)) + SVert);
        }
        while (j < ((s + 1) + cnt)) {
            k = PcKind(ox, j);
            if (k == KStr) {
                PcShowStr(cx, ox, gl, et, f0, f1, f2, f3, j);
            }
            if (k == KNum) {
                delta = ((long) 0) - Fx.FxMuldiv(Fx.FxMul(Fx.FxJoin(PcEa(ox, j), PcEb(ox, j)), fs), (long) 1, (long) 1000);
