                Fx.FxPut(cx, CCur + GTc, PcNum(ox, n, 1));
                PcNextLine(cx);
                PcPrep(src, ar, dc, a, b, st, cx, @out, f0, f1, f2, f3, fnt, et);
                PcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 2);
            }
            return 0;
        }
