            PcDo(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, n);
            return 0;
        }
        if (op == OpBdc) {
            PcMcBegin(src, ar, dc, a, b, st, cx, ox, gl, et, mk, fnt, gx, n, 1);
            return 0;
        }
        if (op == OpBmc) {
            PcMcBegin(src, ar, dc, a, b, st, cx, ox, gl, et, mk, fnt, gx, n, 0);
            return 0;
        }
        if (op == OpEmc) {
            PcMcEnd(cx, mk, gl);
            return 0;
