            return 0;
        }
        if (op == OpClipeo) {
            emon.Port.CellsSet(cx, CClipp, 2);
            return 0;
        }
        if (op == OpSh) {
            PcShOp(cx, pa);
            return 0;
        }
        if (op == OpLw) {
            Fx.FxPut(cx, CCur + GLw, PcNum(ox, n, 0));
            return 0;
        }
        if (op == OpDash) {
            PcDashOp(cx, ox, n);
            return 0;
        }
        return 0;
    }
    internal static int PcRun(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells pa, emon.Port.Cells im, emon.Port.Cells pts, emon.Port.Cells gx, int start, int end) {
        // Run the content bytes cs[start, end): read operands, then execute each
        // operator. The caller's lexer position, graphics-state floor and marked-
        // content floor are kept and restored, so a form can run inside an operator.
        int oldpos = emon.Port.CellsAt(cx, CPos);
        int oldend = emon.Port.CellsAt(cx, CEnd);
        int oldgs = emon.Port.CellsAt(cx, CGsbase);
        int oldmcb = emon.Port.CellsAt(cx, CMcbase);
        int oldover = emon.Port.CellsAt(cx, CMcover);
        int oldtop = emon.Port.CellsAt(cx, CMctop);
        int r = 1;
        int opc = 0;
        int nop = 0;
        int ops = 0;
        emon.Port.CellsSet(cx, CPos, start);
        emon.Port.CellsSet(cx, CEnd, end);
        emon.Port.CellsSet(cx, CGsbase, emon.Port.CellsAt(cx, CDepth));
        emon.Port.CellsSet(cx, CMcbase, emon.Port.CellsAt(cx, CMcdepth));
        emon.Port.CellsSet(cx, CMcover, 0);
        PcOxClear(cx, ox);
        while ((r != 0) && (emon.Port.CellsAt(cx, CAbort) == 0)) {
            r = PcLex(cx, ox, cs);
            if (r == 2) {
                ops = emon.Port.CellsAt(cx, COps) + 1;
                emon.Port.CellsSet(cx, COps, ops);
                if (ops > emon.Port.CellsAt(cx, COplim)) {
                    emon.Port.LimitBreach(5, ops);
                }
                opc = emon.Port.CellsAt(cx, COp);
                nop = emon.Port.CellsAt(cx, COxn);
                PcOp(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, opc, nop);
                PcOxClear(cx, ox);
            }
        }
        // What the stream left open: spans, graphics states.
        while (emon.Port.CellsAt(cx, CMcdepth) > emon.Port.CellsAt(cx, CMcbase)) {
            PcWarnSet(cx, WMc);
            PcMcPop(cx, mk, gl, 1);
        }
        while (emon.Port.CellsAt(cx, CDepth) > emon.Port.CellsAt(cx, CGsbase)) {
            emon.Port.CellsSet(cx, CDepth, emon.Port.CellsAt(cx, CDepth) - 1);
        }
        emon.Port.CellsSet(cx, CMctop, oldtop);
        emon.Port.CellsSet(cx, CCurocg, Evidence.MkOcgOf(mk, oldtop));
        emon.Port.CellsSet(cx, CMcover, oldover);
        emon.Port.CellsSet(cx, CMcbase, oldmcb);
        emon.Port.CellsSet(cx, CGsbase, oldgs);
        emon.Port.CellsSet(cx, CPos, oldpos);
        emon.Port.CellsSet(cx, CEnd, oldend);
        return 0;
    }
    internal const int WordGapPm = 160;
    internal const int WordBackPm = 400;
    internal const int OffsetPm = 450;
    internal const int LineBackPm = 600;
    internal const int LineGapPm = 2000;
    internal static int PcAxis(int rot) {
        // The writing axis a rotation is within three degrees of, else -1 (a glyph run
        // at another angle is measured along its own direction, `pc-rot-gap`).
        int a = ((rot + 4500) / 9000) % 4;
        int d = rot - (a * 9000);
        if (d < 0) {
            d = 0 - d;
        }
        if (d > 18000) {
            d = 36000 - d;
        }
        if (d <= 300) {
            return a;
        }
        return -1;
    }
    internal static int PcOffset(emon.Port.Cells gl, int j, int axis) {
        // Where glyph j's baseline is across its writing axis, in centipoints.
        if (axis == 1) {
            return Evidence.GlGet(gl, j, Evidence.ChX1());
        }
        if (axis == 3) {
            return Evidence.GlGet(gl, j, Evidence.ChX0());
        }
        return Evidence.GlGet(gl, j, Evidence.GfBy0());
    }
    internal static int PcAbs(int v) {
        if (v < 0) {
            return 0 - v;
        }
        return v;
    }
    internal static int PcSheared(emon.Port.Cells gl, int j, int axis) {
        // D1623: 1 when glyph j's box is longer along the writing axis than its baseline segment: the text matrix has a shear term
        // (a synthetic italic: `12 0 4.1041 12 x y Tm`), which leans the cell and makes its axis-aligned box overhang by the shear
        // times the cell's height, on both sides. 0 for the axes a box measures right (and for the others).
        // A glyph with no baseline segment of length (a zero-width mark, or evidence made by hand) is never sheared.
        int bx = PcAbs(Evidence.GlGet(gl, j, Evidence.GfBx1()) - Evidence.GlGet(gl, j, Evidence.GfBx0()));
        int by = PcAbs(Evidence.GlGet(gl, j, Evidence.GfBy1()) - Evidence.GlGet(gl, j, Evidence.GfBy0()));
        if ((axis == 0) || (axis == 2)) {
            if ((bx > 0) && (((Evidence.GlGet(gl, j, Evidence.ChX1()) - Evidence.GlGet(gl, j, Evidence.ChX0())) - bx) > 1)) {
                return 1;
            }
        }
        if ((axis == 1) || (axis == 3)) {
            if ((by > 0) && (((Evidence.GlGet(gl, j, Evidence.ChY1()) - Evidence.GlGet(gl, j, Evidence.ChY0())) - by) > 1)) {
                return 1;
            }
        }
        return 0;
    }
    internal static int PcGap(emon.Port.Cells gl, int p, int g, int axis) {
        // The space along the axis between glyph p and the glyph g after it
        // (negative when they overlap or g is before p). Between leaning glyphs (a shear term in the text matrix) it is the space
        // between the end of p's baseline segment and the origin of g's, which their boxes only measure when they are upright.
        if ((PcSheared(gl, p, axis) == 1) || (PcSheared(gl, g, axis) == 1)) {
            if (axis == 0) {
                return Evidence.GlGet(gl, g, Evidence.GfBx0()) - Evidence.GlGet(gl, p, Evidence.GfBx1());
            }
            if (axis == 2) {
                return Evidence.GlGet(gl, p, Evidence.GfBx1()) - Evidence.GlGet(gl, g, Evidence.GfBx0());
            }
            if (axis == 1) {
                return Evidence.GlGet(gl, p, Evidence.GfBy1()) - Evidence.GlGet(gl, g, Evidence.GfBy0());
            }
            return Evidence.GlGet(gl, g, Evidence.GfBy0()) - Evidence.GlGet(gl, p, Evidence.GfBy1());
        }
        if (axis == 0) {
            return Evidence.GlGet(gl, g, Evidence.ChX0()) - Evidence.GlGet(gl, p, Evidence.ChX1());
        }
        if (axis == 2) {
            return Evidence.GlGet(gl, p, Evidence.ChX0()) - Evidence.GlGet(gl, g, Evidence.ChX1());
        }
        if (axis == 1) {
            return Evidence.GlGet(gl, p, Evidence.ChY0()) - Evidence.GlGet(gl, g, Evidence.ChY1());
        }
        return Evidence.GlGet(gl, g, Evidence.ChY0()) - Evidence.GlGet(gl, p, Evidence.ChY1());
    }
    internal static int PcRotGap(emon.Port.Cells gl, int p, int g, int size) {
        // For text at an arbitrary angle: the distance between glyph p's centre and
        // glyph g's, along the writing direction, less 60 percent of the size (the
        // two half-advances of adjacent letters), so it reads as `pc-gap` does.
        int rot = Evidence.GlGet(gl, p, Evidence.GfRot());
        long ux = Fx.FxCos(rot);
        long uy = ((long) 0) - Fx.FxSin(rot);
        int dx2 = (Evidence.GlGet(gl, g, Evidence.ChX0()) + Evidence.GlGet(gl, g, Evidence.ChX1())) - (Evidence.GlGet(gl, p, Evidence.ChX0()) + Evidence.GlGet(gl, p, Evidence.ChX1()));
        int dy2 = (Evidence.GlGet(gl, g, Evidence.ChY0()) + Evidence.GlGet(gl, g, Evidence.ChY1())) - (Evidence.GlGet(gl, p, Evidence.ChY0()) + Evidence.GlGet(gl, p, Evidence.ChY1()));
        long al2 = unchecked(Fx.FxMul(Fx.FxOfInt(dx2), ux) + Fx.FxMul(Fx.FxOfInt(dy2), uy));
        return Fx.FxRound(al2 / ((long) 2)) - ((size * 600) / 1000);
    }
    internal static int PcRotOff(emon.Port.Cells gl, int p, int g) {
        // The distance between the two glyphs' centres across the writing direction.
        int rot = Evidence.GlGet(gl, p, Evidence.GfRot());
        long sn = Fx.FxSin(rot);
        long cs = Fx.FxCos(rot);
        int dx2 = (Evidence.GlGet(gl, g, Evidence.ChX0()) + Evidence.GlGet(gl, g, Evidence.ChX1())) - (Evidence.GlGet(gl, p, Evidence.ChX0()) + Evidence.GlGet(gl, p, Evidence.ChX1()));
        int dy2 = (Evidence.GlGet(gl, g, Evidence.ChY0()) + Evidence.GlGet(gl, g, Evidence.ChY1())) - (Evidence.GlGet(gl, p, Evidence.ChY0()) + Evidence.GlGet(gl, p, Evidence.ChY1()));
        int pe = Fx.FxRound(unchecked(Fx.FxMul(Fx.FxOfInt(dx2), sn) + Fx.FxMul(Fx.FxOfInt(dy2), cs)) / ((long) 2));
        if (pe < 0) {
            return 0 - pe;
        }
        return pe;
    }
    internal static int PcPairGap(emon.Port.Cells gl, int p, int g, int axis, int size) {
        if (axis < 0) {
            return PcRotGap(gl, p, g, size);
        }
        return PcGap(gl, p, g, axis);
    }
    internal static int PcPairOff(emon.Port.Cells gl, int p, int g, int axis) {
        // How far glyph g's baseline is from glyph p's, across the writing axis.
        if (axis < 0) {
            return PcRotOff(gl, p, g);
        }
        int d = PcOffset(gl, p, axis) - PcOffset(gl, g, axis);
        if (d < 0) {
            return 0 - d;
        }
        return d;
    }
    internal static int PcSpaceCp(int cp) {
        // 1 for a code point that separates words: the spaces (U+0020, U+00A0,
        // U+1680, U+2000..200A, U+202F, U+205F, U+3000) and the tab.
        if ((cp == 32) || ((cp == 160) || ((cp == 9) || ((cp == 5760) || ((cp == 8239) || ((cp == 8287) || (cp == 12288))))))) {
            return 1;
        }
        if ((cp >= 8192) && (cp <= 8202)) {
            return 1;
        }
        return 0;
    }
    internal static int PcCl(int v) {
        // Clamp a distance to +-1,000,000 centipoints so a per-mille product fits an I32.
        if (v > 1000000) {
            return 1000000;
        }
        if (v < -1000000) {
            return -1000000;
        }
        return v;
    }
    internal static int PcRotSame(int r1, int r2) {
        // 1 when two rotations (centi-degrees) agree to half a degree.
        int d = r1 - r2;
        if (d < 0) {
            d = 0 - d;
        }
        if (d > 18000) {
            d = 36000 - d;
        }
        if (d <= 50) {
            return 1;
        }
        return 0;
    }
    internal static int PcHiddenMode(int mode) {
        // 1 for the invisible render modes, 3 and 7.
        if ((mode == 3) || (mode == 7)) {
            return 1;
        }
        return 0;
    }
    internal static int PcAccent(int cp) {
        // D1625: the combining mark a spacing diacritic stands for when it is drawn over a letter (TeX draws an umlaut as the glyph
        // dieresis, then the u under it): the dieresis, acute, grave, macron, cedilla, circumflex, caron, breve, dot above, ring,
        // ogonek, small tilde and double acute. 0 for anything else.
        if (cp == 168) {
            return 776;
        }
        if (cp == 180) {
            return 769;
        }
        if (cp == 96) {
            return 768;
        }
        if (cp == 175) {
            return 772;
        }
        if (cp == 184) {
            return 807;
        }
        if (cp == 710) {
            return 770;
        }
        if (cp == 711) {
            return 780;
        }
        if (cp == 728) {
            return 774;
        }
        if (cp == 729) {
            return 775;
        }
        if (cp == 730) {
            return 778;
        }
        if (cp == 731) {
            return 808;
        }
        if (cp == 732) {
            return 771;
        }
        if (cp == 733) {
            return 779;
        }
        return 0;
    }
    internal static int PcAccentOver(emon.Port.Cells gl, int p, int g) {
        // D1625: the combining mark that glyph p is when it is a spacing diacritic standing over glyph g, a letter drawn right
        // after it: both upright and of one rotation, no text of their own beyond the one code point, and the middle of the diacritic
        // within the letter's width (Muller is M, the dieresis, then uller backed up under it). 0 when it is not.
        int comb = PcAccent(Evidence.GlGet(gl, p, Evidence.ChCp()));
        int cx2 = Evidence.GlGet(gl, p, Evidence.ChX0()) + Evidence.GlGet(gl, p, Evidence.ChX1());
        if (comb == 0) {
            return 0;
        }
        if (Evidence.GlGet(gl, p, Evidence.ChTstart()) >= 0) {
            return 0;
        }
        if (Evidence.GlGet(gl, g, Evidence.ChTstart()) >= 0) {
            return 0;
        }
        if (Bidi.BdStrong(Evidence.GlGet(gl, g, Evidence.ChCp())) != 2) {
            return 0;
        }
        if (PcAxis(Evidence.GlGet(gl, p, Evidence.GfRot())) != 0) {
            return 0;
        }
        if (PcRotSame(Evidence.GlGet(gl, p, Evidence.GfRot()), Evidence.GlGet(gl, g, Evidence.GfRot())) == 0) {
            return 0;
        }
        if (Evidence.GlGet(gl, p, Evidence.GfVis()) != Evidence.GlGet(gl, g, Evidence.GfVis())) {
            return 0;
        }
        if (cx2 < (2 * Evidence.GlGet(gl, g, Evidence.ChX0()))) {
            return 0;
        }
        if (cx2 > (2 * Evidence.GlGet(gl, g, Evidence.ChX1()))) {
            return 0;
        }
        return comb;
    }
    internal static int PcAccentPair(emon.Port.Cells gl, int j, int glst) {
        // The combining mark glyph j is when it is a spacing diacritic over glyph j+1, which is in the same word (j+1 <= glst); else 0.
        if (j >= glst) {
            return 0;
        }
        return PcAccentOver(gl, j, j + 1);
    }
    internal static int PcContinues(emon.Port.Cells gl, int p, int g) {
        // 1 when glyph g continues the word glyph p is in: the same rotation, on the
        // same baseline (to 45 percent of the size: sub- and superscripts stay), and
        // the gap along the axis neither a word space nor a step back.
        int rot = Evidence.GlGet(gl, p, Evidence.GfRot());
        int axis = PcAxis(rot);
        int size = Evidence.GlGet(gl, g, Evidence.GfSize());
        int sizep = Evidence.GlGet(gl, p, Evidence.GfSize());
        int sz = size;
        int gap = 0;
        int off = 0;
        if (PcRotSame(rot, Evidence.GlGet(gl, g, Evidence.GfRot())) == 0) {
            return 0;
        }
        // A word is one thing to see: a glyph of another visibility, or one that is hidden (mode 3, 7) where the other
        // is not, starts a new word (P3.6).
        if (Evidence.GlGet(gl, p, Evidence.GfVis()) != Evidence.GlGet(gl, g, Evidence.GfVis())) {
            return 0;
        }
        if (PcHiddenMode(Evidence.GlGet(gl, p, Evidence.GfMode())) != PcHiddenMode(Evidence.GlGet(gl, g, Evidence.GfMode()))) {
            return 0;
        }
        // A spacing diacritic over the letter drawn right after it is part of that letter's word (D1625).
        if (PcAccentOver(gl, p, g) > 0) {
            return 1;
        }
        if (sizep > sz) {
            sz = sizep;
        }
        if (sz > 200000) {
            sz = 200000;
        }
        if (sz < (0 - 200000)) {
            sz = 0 - 200000;
        }
        off = PcCl(PcPairOff(gl, p, g, axis));
        if ((off * 1000) > (sz * OffsetPm)) {
            return 0;
        }
        gap = PcCl(PcPairGap(gl, p, g, axis, sz));
        if ((gap * 1000) > (sz * WordGapPm)) {
            return 0;
        }
        if ((gap * 1000) < (0 - (sz * WordBackPm))) {
            return 0;
        }
        return 1;
    }
    internal static int PcGcls(emon.Port.Cells gl, int j) {
        // 1 when glyph j stands for a strong right-to-left LETTER (Hebrew, Arabic, Syriac, ...: the Unicode class R or
        // AL), 2 for a strong left-to-right letter, else 0. Letters decide the direction of a word and of a line (D162);
        // a digit, a separator or a mark does not.
        return Bidi.BdStrong(Evidence.GlGet(gl, j, Evidence.ChCp()));
    }
    internal static int PcGlyphOut(emon.Port.Cells et, emon.Port.Cells gl, int j, int lvl) {
        // Append glyph j's text (every code point it stands for, or U+FFFD) to the evidence text. At bidi level 1
        // (lvl, L4) a text of ONE code point whose character is mirrored (a bracket) is the mirror: the glyph on the
        // page was drawn as the mirror image of the character it stands for.
        int ts = Evidence.GlGet(gl, j, Evidence.ChTstart());
        int tl = Evidence.GlGet(gl, j, Evidence.ChTlen());
        int cp = Evidence.GlGet(gl, j, Evidence.ChCp());
        int k = 0;
        int cpv = 0;
        if ((ts >= 0) && (tl > 0)) {
            while (k < tl) {
                cpv = emon.Port.CellsAt(et, ts + k);
                if ((lvl == 1) && (tl == 1)) {
                    cpv = Bidi.BdMirror(cpv);
                }
                Evidence.EtxAppendCp(et, cpv);
                k += 1;
            }
            return 0;
        }
        if (cp >= 0) {
            if (lvl == 1) {
                cp = Bidi.BdMirror(cp);
            }
            Evidence.EtxAppendCp(et, cp);
        } else {
            Evidence.EtxAppendCp(et, 65533);
        }
        return 0;
    }
    internal static int PcBidiText(emon.Port.Cells et, emon.Port.Cells gl, int gfst, int glst) {
        // Append the text of glyphs [gfst, glst], which were SHOWN left to right, in LOGICAL order of a right-to-left
        // paragraph (`emon.bidi`, D162): the order the Bidirectional Algorithm would display them in. It is written
        // where the arena ended, moved down over the scratch the algorithm used, and the index it starts at is the
        // answer. (The scratch is the arena's own tail: the algorithm owns no memory.)
        int n = (glst - gfst) + 1;
        int b = emon.Port.CellsLen(et);
        int j = 0;
        int o = 0;
        int e = 0;
        int i = 0;
        int lv = 0;
        int k = 0;
        while (j < n) {
            emon.Port.CellsPush(et, Evidence.GlGet(gl, gfst + j, Evidence.ChCp()));
            j += 1;
        }
        o = Bidi.BdOrderOf(et, b, n);
        e = emon.Port.CellsLen(et);
        j = 0;
        while (j < n) {
            i = emon.Port.CellsAt(et, o + j);
            lv = emon.Port.CellsAt(et, (o - n) + i);
            PcGlyphOut(et, gl, gfst + i, lv);
            j += 1;
        }
        k = 0;
        while (k < (emon.Port.CellsLen(et) - e)) {
            emon.Port.CellsSet(et, b + k, emon.Port.CellsAt(et, e + k));
            k += 1;
        }
        emon.Port.CellsDrop(et, b + (emon.Port.CellsLen(et) - e));
        return b;
    }
    internal static int PcEmitWord(emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells wd, emon.Port.Cells fnt, int page, int gfst, int glst, int wbk) {
        // Record glyphs [gfst, glst] as a word: the union of their boxes, their text, the
        // dominant font and size of the first, and `hidden-text` as its source when every
        // glyph is render mode 3. A right-to-left word whose glyphs run left to right on the
        // page (visual order, as Skia and most producers write them) has its TEXT written in
        // logical order by the Bidirectional Algorithm (`pc-bidi-text`, D162): numbers and their separators,
        // Latin runs, brackets and the neutrals between them as UAX #9 resolves them, not letter by letter. A word
        // with no letter to say so ("2026,") is put right once its line is known to be right to left
        // (`pc-word-fix`). The glyphs themselves stay as they were shown.
        int x0 = Evidence.GlGet(gl, gfst, Evidence.ChX0());
        int y0 = Evidence.GlGet(gl, gfst, Evidence.ChY0());
        int x1 = Evidence.GlGet(gl, gfst, Evidence.ChX1());
        int y1 = Evidence.GlGet(gl, gfst, Evidence.ChY1());
        int j = gfst;
        int tstart = -1;
        int visible = 0;
        int nr = 0;
        int nl = 0;
        int cl = 0;
        int rtlw = 0;
        while (j <= glst) {
            if (Evidence.GlGet(gl, j, Evidence.ChX0()) < x0) {
                x0 = Evidence.GlGet(gl, j, Evidence.ChX0());
            }
            if (Evidence.GlGet(gl, j, Evidence.ChY0()) < y0) {
                y0 = Evidence.GlGet(gl, j, Evidence.ChY0());
            }
            if (Evidence.GlGet(gl, j, Evidence.ChX1()) > x1) {
                x1 = Evidence.GlGet(gl, j, Evidence.ChX1());
            }
            if (Evidence.GlGet(gl, j, Evidence.ChY1()) > y1) {
                y1 = Evidence.GlGet(gl, j, Evidence.ChY1());
            }
            if ((Evidence.GlGet(gl, j, Evidence.GfMode()) != 3) && (Evidence.GlGet(gl, j, Evidence.GfMode()) != 7)) {
                visible = 1;
            }
            cl = PcGcls(gl, j);
            if (cl == 1) {
                nr += 1;
            }
            if (cl == 2) {
                nl += 1;
            }
            j += 1;
        }
        if ((nr > nl) && (glst > gfst)) {
            if (PcAxis(Evidence.GlGet(gl, gfst, Evidence.GfRot())) == 0) {
                if (Evidence.GlGet(gl, glst, Evidence.ChX0()) >= Evidence.GlGet(gl, gfst, Evidence.ChX0())) {
                    rtlw = 1;
                }
            }
        }
        tstart = emon.Port.CellsLen(et);
        if (rtlw == 0) {
            j = gfst;
            while (j <= glst) {
                // a spacing diacritic over the next letter of the word is written AFTER the letter, as the combining mark (D1625)
                cl = PcAccentPair(gl, j, glst);
                if (cl > 0) {
                    PcGlyphOut(et, gl, j + 1, 2);
                    Evidence.EtxAppendCp(et, cl);
                    j += 2;
                } else {
                    PcGlyphOut(et, gl, j, 2);
                    j += 1;
                }
            }
        } else {
            tstart = PcBidiText(et, gl, gfst, glst);
        }
        int w = Evidence.WdNew(wd, page, x0, y0, x1, y1, Evidence.GlGet(gl, gfst, Evidence.GfBx0()), Evidence.GlGet(gl, gfst, Evidence.GfBy0()), Evidence.GlGet(gl, glst, Evidence.GfBx1()), Evidence.GlGet(gl, glst, Evidence.GfBy1()), Evidence.GlGet(gl, gfst, Evidence.GfRot()), 0, tstart, emon.Port.CellsLen(et) - tstart, -1, -1, -1);
        int fo = Evidence.GlGet(gl, gfst, Evidence.GfFont());
        if (rtlw == 1) {
            Evidence.WdSet(wd, w, Evidence.HdDir(), Evidence.LdRtl());
        }
        Evidence.WdSet(wd, w, Evidence.WfGfirst(), gfst);
        Evidence.WdSet(wd, w, Evidence.WfGcount(), (glst - gfst) + 1);
        Evidence.WdSet(wd, w, Evidence.WfFont(), fo);
        Evidence.WdSet(wd, w, Evidence.WfSize(), Evidence.GlGet(gl, gfst, Evidence.GfSize()));
        if ((fo >= 0) && (fo < Evidence.FoCount(fnt))) {
            Evidence.WdSet(wd, w, Evidence.WfStyle(), Evidence.FoGet(fnt, fo, Evidence.FnfStyle()));
        }
        Evidence.WdSet(wd, w, Evidence.WfWbreak(), wbk);
        if (visible == 0) {
            Evidence.WdSet(wd, w, Evidence.WfSrc(), Model.SrHiddenText());
        }
        j = gfst;
        while (j <= glst) {
            Evidence.GlSet(gl, j, Evidence.ChWord(), w);
            j += 1;
        }
        return w;
    }
    internal static int PcSwapRows(emon.Port.Cells wd, int i, int j) {
        int k = 0;
        int u = 0;
        int v = 0;
        while (k < 24) {
            u = emon.Port.CellsAt(wd, (i * 24) + k);
            v = emon.Port.CellsAt(wd, (j * 24) + k);
            emon.Port.CellsSet(wd, (i * 24) + k, v);
            emon.Port.CellsSet(wd, (j * 24) + k, u);
            k += 1;
        }
        return 0;
    }
    internal static int PcRevRows(emon.Port.Cells wd, int a, int b) {
        int i = a;
        int j = b;
        while (i < j) {
            PcSwapRows(wd, i, j);
            i += 1;
            j -= 1;
        }
        return 0;
    }
    internal static int PcWcls(emon.Port.Cells gl, emon.Port.Cells wd, int w) {
        // What a word is to the order of the words of a right-to-left line: 1 when it has a right-to-left letter,
        // 2 when it has a left-to-right letter and no right-to-left one, 3 when it is only numbers (and what goes
        // with them), 0 when it is only neutrals (a dash, a bullet).
        int g0 = Evidence.WdGet(wd, w, Evidence.WfGfirst());
        int gn = Evidence.WdGet(wd, w, Evidence.WfGcount());
        int j = 0;
        int nr = 0;
        int nl = 0;
        int nn = 0;
        int cl = 0;
        while (j < gn) {
            cl = PcGcls(gl, g0 + j);
            if (cl == 1) {
                nr += 1;
            }
            if (cl == 2) {
                nl += 1;
            }
            cl = Bidi.BdClass(Evidence.GlGet(gl, g0 + j, Evidence.ChCp()));
            if ((cl == 3) || (cl == 4)) {
                nn += 1;
            }
            j += 1;
        }
        if (nr > 0) {
            return 1;
        }
        if (nl > 0) {
            return 2;
        }
        if (nn > 0) {
            return 3;
        }
        return 0;
    }
    internal static int PcWordFix(emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells wd, int w) {
        // A word of a right-to-left line that `pc-emit-word` left in the order it was shown, because nothing in it
        // said it was right to left ("2026,", "50%", "(1)", "ROI-" before a Hebrew letter): when its glyphs run
        // left to right on the page they are in visual order, so its text is put in logical order, as a word that
        // says so is. Done in place: the same code points, in the order the algorithm gives; nothing moves if the
        // order does not change. Answers 1 when it changed the text.
        int g0 = Evidence.WdGet(wd, w, Evidence.WfGfirst());
        int gn = Evidence.WdGet(wd, w, Evidence.WfGcount());
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        int b = emon.Port.CellsLen(et);
        int j = 0;
        int o = 0;
        int e = 0;
        int i = 0;
        int lv = 0;
        int changed = 0;
        if (gn < 2) {
            return 0;
        }
        if (Evidence.WdGet(wd, w, Evidence.HdDir()) == Evidence.LdRtl()) {
            return 0;
        }
        if (PcAxis(Evidence.GlGet(gl, g0, Evidence.GfRot())) != 0) {
            return 0;
        }
        if (Evidence.GlGet(gl, g0 + (gn - 1), Evidence.ChX0()) < Evidence.GlGet(gl, g0, Evidence.ChX0())) {
            return 0;
        }
        while (j < gn) {
            emon.Port.CellsPush(et, Evidence.GlGet(gl, g0 + j, Evidence.ChCp()));
            j += 1;
        }
        o = Bidi.BdOrderOf(et, b, gn);
        j = 0;
        while (j < gn) {
            i = emon.Port.CellsAt(et, o + j);
            lv = emon.Port.CellsAt(et, (o - gn) + i);
            if ((i != j) || (lv == 1)) {
                changed = 1;
            }
            j += 1;
        }
        if (changed == 0) {
            emon.Port.CellsDrop(et, b);
            return 0;
        }
        e = emon.Port.CellsLen(et);
        j = 0;
        while (j < gn) {
            i = emon.Port.CellsAt(et, o + j);
            lv = emon.Port.CellsAt(et, (o - gn) + i);
            PcGlyphOut(et, gl, g0 + i, lv);
            j += 1;
        }
        if ((emon.Port.CellsLen(et) - e) != tl) {
            emon.Port.CellsDrop(et, b);
            return 0;
        }
        j = 0;
        while (j < tl) {
            emon.Port.CellsSet(et, ts + j, emon.Port.CellsAt(et, e + j));
            j += 1;
        }
        emon.Port.CellsDrop(et, b);
        return 1;
    }
    internal static int PcLineBidi(emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells wd, emon.Port.Cells ln, int lidx, int wfst, int wlst) {
        // Line lidx holds words [wfst, wlst]. When more of its letters are right-to-left than left-to-right
        // it is a right-to-left line (`ld-rtl`). Its words that no letter put in logical order are put in it
        // (`pc-word-fix`); if the words run left to right on the page, their ORDER is made logical: reversed,
        // with each group of words that make one left-to-right run (Latin words, and the numbers and neutrals
        // between them, W7 and N1) turned back; each word's glyphs are re-pointed at it and its gap is the
        // space to the word that follows it in that order.
        int w = wfst;
        int nr = 0;
        int nl = 0;
        int j = 0;
        int cl = 0;
        int a = 0;
        int z = 0;
        int s = 0;
        int hasl = 0;
        int rtl = 0;
        int g0 = 0;
        int gn = 0;
        while (w <= wlst) {
            g0 = Evidence.WdGet(wd, w, Evidence.WfGfirst());
            gn = Evidence.WdGet(wd, w, Evidence.WfGcount());
            j = 0;
            while (j < gn) {
                cl = PcGcls(gl, g0 + j);
                if (cl == 1) {
                    nr += 1;
                }
                if (cl == 2) {
                    nl += 1;
                }
                j += 1;
            }
            w += 1;
        }
        // A paragraph's direction is its own, not each line's: a short last line that is mostly Latin (a
        // product name, an acronym) after a right-to-left line is still right to left (UAX #9, P2 and P3 read
        // the paragraph, and the lines of one run on). So a line is right to left when its right-to-left
        // letters outnumber the left-to-right ones, or when the line before it (same page) is and this one has a
        // right-to-left letter or no left-to-right one (a number, a bullet).
        rtl = 0;
        if (nr > nl) {
            rtl = 1;
        }
        if ((lidx > 0) && (rtl == 0)) {
            if (Evidence.LnGet(ln, lidx - 1, Evidence.LhPage()) == Evidence.LnGet(ln, lidx, Evidence.LhPage())) {
                if (Evidence.LnGet(ln, lidx - 1, Evidence.LhDir()) == Evidence.LdRtl()) {
                    if ((nr > 0) || (nl == 0)) {
                        rtl = 1;
                    }
                }
            }
        }
        if (rtl == 0) {
            return 0;
        }
        Evidence.LnSet(ln, lidx, Evidence.LhDir(), Evidence.LdRtl());
        w = wfst;
        while (w <= wlst) {
            PcWordFix(gl, et, wd, w);
            w += 1;
        }
        if (PcAxis(Evidence.GlGet(gl, Evidence.WdGet(wd, wfst, Evidence.WfGfirst()), Evidence.GfRot())) != 0) {
            return 0;
        }
        if (Evidence.WdGet(wd, wlst, Evidence.HdX0()) < Evidence.WdGet(wd, wfst, Evidence.HdX0())) {
            return 0;
        }
        if (wfst == wlst) {
            return 0;
        }
        PcRevRows(wd, wfst, wlst);
        // Now the rows are in logical order but for the left-to-right runs, which are backwards: a run is a
        // maximal stretch of words that are not right-to-left, holding at least one left-to-right word, less
        // the neutral-only words at its ends (they are between a left-to-right and a right-to-left word: N2).
        a = wfst;
        while (a <= wlst) {
            if (PcWcls(gl, wd, a) == 1) {
                a += 1;
            } else {
                z = a;
                while ((z < wlst) && (PcWcls(gl, wd, z + 1) != 1)) {
                    z += 1;
                }
                hasl = 0;
                s = a;
                while (s <= z) {
                    if (PcWcls(gl, wd, s) == 2) {
                        hasl = 1;
                    }
                    s += 1;
                }
                if (hasl == 1) {
                    s = a;
                    while (PcWcls(gl, wd, s) == 0) {
                        s += 1;
                    }
                    j = z;
                    while (PcWcls(gl, wd, j) == 0) {
                        j -= 1;
                    }
                    PcRevRows(wd, s, j);
                }
                a = z + 1;
            }
        }
        w = wfst;
        while (w <= wlst) {
            g0 = Evidence.WdGet(wd, w, Evidence.WfGfirst());
            gn = Evidence.WdGet(wd, w, Evidence.WfGcount());
            j = 0;
            while (j < gn) {
                Evidence.GlSet(gl, g0 + j, Evidence.ChWord(), w);
                j += 1;
            }
            z = -1;
            if (w < wlst) {
                z = Evidence.WdGet(wd, w, Evidence.HdX0()) - Evidence.WdGet(wd, w + 1, Evidence.HdX1());
            }
            Evidence.WdSet(wd, w, Evidence.WfGap(), z);
            w += 1;
        }
        return 0;
    }
    internal const int Nojoin = 2000000;
    internal const int MergeMax = 256;
    internal static int PcSameBase(emon.Port.Cells gl, emon.Port.Cells wd, int p, int j) {
        // 1 when word j is on word p's baseline: the same rotation, and the offset across the writing axis, from p's last glyph to j's
        // first, within `OFFSET_PM` of the larger size.
        int gfp = Evidence.WdGet(wd, p, Evidence.WfGfirst());
        int gf0 = Evidence.WdGet(wd, j, Evidence.WfGfirst());
        int axis = PcAxis(Evidence.GlGet(gl, gfp, Evidence.GfRot()));
        int sz = Evidence.GlGet(gl, gf0, Evidence.GfSize());
        int glast = (gfp + Evidence.WdGet(wd, p, Evidence.WfGcount())) - 1;
        if (PcRotSame(Evidence.GlGet(gl, gfp, Evidence.GfRot()), Evidence.GlGet(gl, gf0, Evidence.GfRot())) == 0) {
            return 0;
        }
        if (Evidence.GlGet(gl, gfp, Evidence.GfSize()) > sz) {
            sz = Evidence.GlGet(gl, gfp, Evidence.GfSize());
        }
        if (sz > 200000) {
            sz = 200000;
        }
        if (sz < (0 - 200000)) {
            sz = 0 - 200000;
        }
        if ((PcCl(PcPairOff(gl, glast, gf0, axis)) * 1000) <= (sz * OffsetPm)) {
            return 1;
        }
        return 0;
    }
    internal static int PcJoinGap(emon.Port.Cells gl, emon.Port.Cells wd, int p, int j) {
        // The rule that puts word j on word p's line: the same rotation and baseline (`pc-same-base`), and a gap from p's LAST glyph to j's
        // first that is at most `LINE_GAP_PM` of the larger size and at most `LINE_BACK_PM` back. Answers the gap, or `NOJOIN`.
        int gfp = Evidence.WdGet(wd, p, Evidence.WfGfirst());
        int gf0 = Evidence.WdGet(wd, j, Evidence.WfGfirst());
        int axis = PcAxis(Evidence.GlGet(gl, gfp, Evidence.GfRot()));
        int sz = Evidence.GlGet(gl, gf0, Evidence.GfSize());
        int gap = 0;
        int glast = (gfp + Evidence.WdGet(wd, p, Evidence.WfGcount())) - 1;
        if (PcSameBase(gl, wd, p, j) == 0) {
            return Nojoin;
        }
        if (Evidence.GlGet(gl, gfp, Evidence.GfSize()) > sz) {
            sz = Evidence.GlGet(gl, gfp, Evidence.GfSize());
        }
        if (sz > 200000) {
            sz = 200000;
        }
        if (sz < (0 - 200000)) {
            sz = 0 - 200000;
        }
        // The gap is between the previous word's LAST glyph and this word's first.
        gap = PcCl(PcPairGap(gl, glast, gf0, axis, sz));
        if ((gap * 1000) < (0 - (sz * LineBackPm))) {
            return Nojoin;
        }
        if ((gap * 1000) > (sz * LineGapPm)) {
            return Nojoin;
        }
        return gap;
    }
    internal static int PcMergeSpan(emon.Port.Cells gl, emon.Port.Cells wd, int s, int t) {
        // Words [s, t] are runs of the stream on one baseline that are not in order along it. When every one is horizontal, of one visibility
        // and has no right-to-left letter, and each word, taken in order of x, joins the one after it by `pc-join-gap`, they are put in that
        // order (a stable insertion sort of the word rows; the glyphs are pointed at their word again) and are one line to the loop that
        // follows. Otherwise nothing moves. Answers 1 when the words were put in order.
        int g0 = Evidence.WdGet(wd, s, Evidence.WfGfirst());
        int i = s;
        int j = 0;
        int k = 0;
        int best = 0;
        int asc = 1;
        int gi = 0;
        i = s + 1;
        while (i <= t) {
            if (Evidence.WdGet(wd, i, Evidence.HdX0()) < Evidence.WdGet(wd, i - 1, Evidence.HdX0())) {
                asc = 0;
            }
            i += 1;
        }
        if (asc == 1) {
            return 0;
        }
        i = s;
        while (i <= t) {
            gi = Evidence.WdGet(wd, i, Evidence.WfGfirst());
            if (PcAxis(Evidence.GlGet(gl, gi, Evidence.GfRot())) != 0) {
                return 0;
            }
            if (Evidence.GlGet(gl, gi, Evidence.GfVis()) != Evidence.GlGet(gl, g0, Evidence.GfVis())) {
                return 0;
            }
            if (PcHiddenMode(Evidence.GlGet(gl, gi, Evidence.GfMode())) != PcHiddenMode(Evidence.GlGet(gl, g0, Evidence.GfMode()))) {
                return 0;
            }
            if (Evidence.WdGet(wd, i, Evidence.HdDir()) == Evidence.LdRtl()) {
                return 0;
            }
            if (PcWcls(gl, wd, i) == 1) {
                return 0;
            }
            i += 1;
        }
        // Each word's successor in order of x (ties by place in the stream): it must continue the word.
        i = s;
        while (i <= t) {
            best = -1;
            j = s;
            while (j <= t) {
                if ((Evidence.WdGet(wd, j, Evidence.HdX0()) > Evidence.WdGet(wd, i, Evidence.HdX0())) || ((Evidence.WdGet(wd, j, Evidence.HdX0()) == Evidence.WdGet(wd, i, Evidence.HdX0())) && (j > i))) {
                    if (best < 0) {
                        best = j;
                    } else if (Evidence.WdGet(wd, j, Evidence.HdX0()) < Evidence.WdGet(wd, best, Evidence.HdX0())) {
                        best = j;
                    }
                }
                j += 1;
            }
            if (best >= 0) {
                if (PcJoinGap(gl, wd, i, best) >= Nojoin) {
                    return 0;
                }
            }
            i += 1;
        }
        i = s + 1;
        while (i <= t) {
            j = i;
            while ((j > s) && (Evidence.WdGet(wd, j - 1, Evidence.HdX0()) > Evidence.WdGet(wd, j, Evidence.HdX0()))) {
                PcSwapRows(wd, j - 1, j);
                j -= 1;
            }
            i += 1;
        }
        i = s;
        while (i <= t) {
            gi = Evidence.WdGet(wd, i, Evidence.WfGfirst());
            k = 0;
            while (k < Evidence.WdGet(wd, i, Evidence.WfGcount())) {
                Evidence.GlSet(gl, gi + k, Evidence.ChWord(), i);
                k += 1;
            }
            if ((i < t) && (Evidence.WdGet(wd, i, Evidence.WfWbreak()) == Evidence.WbLineEnd())) {
                Evidence.WdSet(wd, i, Evidence.WfWbreak(), Evidence.WbGap());
            }
            i += 1;
        }
        return 1;
    }
    internal static int PcMergeLines(emon.Port.Cells gl, emon.Port.Cells wd, int w0) {
        // The words from w0 on, before they are cut into lines: where consecutive runs of the stream (each a stretch of words that
        // `pc-join-gap` joins) are on one baseline, they are one candidate (at most `MERGE_MAX` words) and `pc-merge-span` puts them in
        // order along it if they make one line. A run that is already in order along the baseline is left alone (a wide gap in it ends the line, as
        // ever: a column gutter or a table cell). Answers the spans put in order.
        int nw = Evidence.WdCount(wd);
        int s = w0;
        int t = 0;
        int u = 0;
        int nseg = 0;
        int more = 0;
        int done = 0;
        while (s < nw) {
            t = s;
            while (((t + 1) < nw) && (PcJoinGap(gl, wd, t, t + 1) < Nojoin)) {
                t += 1;
            }
            nseg = 1;
            more = 1;
            while ((more == 1) && (((t + 1) < nw) && ((t - s) < MergeMax))) {
                if (PcSameBase(gl, wd, t, t + 1) == 1) {
                    u = t + 1;
                    while (((u + 1) < nw) && (PcJoinGap(gl, wd, u, u + 1) < Nojoin)) {
                        u += 1;
                    }
                    t = u;
                    nseg += 1;
                } else {
                    more = 0;
                }
            }
            if ((nseg > 1) && ((t - s) <= MergeMax)) {
                done += PcMergeSpan(gl, wd, s, t);
            }
            s = t + 1;
        }
        return done;
    }
    public static int PcGroup(emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells fnt, int page, int g0, int w0) {
        // Group the glyphs from g0 on into words, and the words from w0 on into lines.
        int g1 = Evidence.GlCount(gl);
        int i = g0;
        int cur = -1;
        while (i < g1) {
            if (PcSpaceCp(Evidence.GlGet(gl, i, Evidence.ChCp())) == 1) {
                if (cur >= 0) {
                    PcEmitWord(gl, et, wd, fnt, page, cur, i - 1, Evidence.WbSpace());
                    cur = -1;
                }
            } else {
                if (cur >= 0) {
                    if (PcContinues(gl, i - 1, i) == 0) {
                        PcEmitWord(gl, et, wd, fnt, page, cur, i - 1, Evidence.WbGap());
                        cur = -1;
                    }
                }
                if (cur < 0) {
                    cur = i;
                }
            }
            i += 1;
        }
        if (cur >= 0) {
            PcEmitWord(gl, et, wd, fnt, page, cur, g1 - 1, Evidence.WbLineEnd());
            cur = -1;
        }
        // Lines: consecutive words on one baseline, in order.
        int nw = Evidence.WdCount(wd);
        int j = w0;
        int lfirst = -1;
        int prev = -1;
        int lnx = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int gfp = 0;
        int joins = 0;
        int gap = 0;
        int ord = 0;
        PcMergeLines(gl, wd, w0);
        while (j <= nw) {
            joins = 0;
            if ((j < nw) && (prev >= 0)) {
                gap = PcJoinGap(gl, wd, prev, j);
                if (gap < Nojoin) {
                    joins = 1;
                }
            }
            if (joins == 1) {
                Evidence.WdSet(wd, prev, Evidence.WfGap(), gap);
                prev = j;
            } else {
                // The line so far ends at `prev`: record it, then start a new one at j.
                if (lfirst >= 0) {
                    x0 = Evidence.WdGet(wd, lfirst, Evidence.HdX0());
                    y0 = Evidence.WdGet(wd, lfirst, Evidence.HdY0());
                    x1 = Evidence.WdGet(wd, lfirst, Evidence.HdX1());
                    y1 = Evidence.WdGet(wd, lfirst, Evidence.HdY1());
                    lnx = lfirst;
                    while (lnx <= prev) {
                        if (Evidence.WdGet(wd, lnx, Evidence.HdX0()) < x0) {
                            x0 = Evidence.WdGet(wd, lnx, Evidence.HdX0());
                        }
                        if (Evidence.WdGet(wd, lnx, Evidence.HdY0()) < y0) {
                            y0 = Evidence.WdGet(wd, lnx, Evidence.HdY0());
                        }
                        if (Evidence.WdGet(wd, lnx, Evidence.HdX1()) > x1) {
                            x1 = Evidence.WdGet(wd, lnx, Evidence.HdX1());
                        }
                        if (Evidence.WdGet(wd, lnx, Evidence.HdY1()) > y1) {
                            y1 = Evidence.WdGet(wd, lnx, Evidence.HdY1());
                        }
                        lnx += 1;
                    }
                    gfp = Evidence.WdGet(wd, lfirst, Evidence.WfGfirst());
                    ord = Evidence.WdGet(wd, lfirst, Evidence.WfGfirst());
                    lnx = lfirst;
                    while (lnx <= prev) {
                        if (Evidence.WdGet(wd, lnx, Evidence.WfGfirst()) < ord) {
                            ord = Evidence.WdGet(wd, lnx, Evidence.WfGfirst());
                        }
                        lnx += 1;
                    }
                    // The baseline runs from the first word's start to the last word's end, in the
                    // order the words were SHOWN (the bidi step below re-orders the rows, not the page).
                    lnx = Evidence.LnNew(ln, page, x0, y0, x1, y1, Evidence.WdGet(wd, lfirst, Evidence.HdBx0()), Evidence.WdGet(wd, lfirst, Evidence.HdBy0()), Evidence.WdGet(wd, prev, Evidence.HdBx1()), Evidence.WdGet(wd, prev, Evidence.HdBy1()), Evidence.GlGet(gl, gfp, Evidence.GfRot()), 0, lfirst, (prev - lfirst) + 1);
                    Evidence.LnSet(ln, lnx, Evidence.LfOrder(), ord);
                    PcLineBidi(gl, et, wd, ln, lnx, lfirst, prev);
                    Evidence.WdSet(wd, prev, Evidence.WfWbreak(), Evidence.WbLineEnd());
                    gfp = lfirst;
                    while (gfp <= prev) {
                        Evidence.WdSet(wd, gfp, Evidence.HdLine(), lnx);
                        gfp += 1;
                    }
                }
                lfirst = j;
                prev = j;
            }
            j += 1;
        }
        return 0;
    }
    internal static int PcBeginPage(emon.Port.Cells cx, int page) {
        // Reset everything a page owns; the fonts (the document's) stay.
        emon.Port.CellsSet(cx, CPage, page);
        emon.Port.CellsSet(cx, CWarn, 0);
        emon.Port.CellsSet(cx, COps, 0);
        emon.Port.CellsSet(cx, CAbort, 0);
        emon.Port.CellsSet(cx, CPos, 0);
        emon.Port.CellsSet(cx, CEnd, 0);
        emon.Port.CellsSet(cx, COxn, 0);
        emon.Port.CellsSet(cx, CCdepth, 0);
        emon.Port.CellsSet(cx, COp, 0);
        emon.Port.CellsSet(cx, CRes, 0);
        emon.Port.CellsSet(cx, CSlot, -1);
        emon.Port.CellsSet(cx, CDepth, 0);
        emon.Port.CellsSet(cx, CFdepth, 0);
        emon.Port.CellsSet(cx, CStm, 0);
        emon.Port.CellsSet(cx, CMctop, -1);
        emon.Port.CellsSet(cx, CMcdepth, 0);
        emon.Port.CellsSet(cx, CMcbase, 0);
        emon.Port.CellsSet(cx, CMcover, 0);
        emon.Port.CellsSet(cx, CCurocg, -1);
        emon.Port.CellsSet(cx, CZ, 0);
        emon.Port.CellsSet(cx, CIntext, 0);
        emon.Port.CellsSet(cx, CClipp, 0);
        emon.Port.CellsSet(cx, CTcn, 0);
        emon.Port.CellsSet(cx, CNpath, 0);
        emon.Port.CellsSet(cx, CNimg, 0);
        emon.Port.CellsSet(cx, CGsbase, 0);
        Fx.MxIdent(cx, CTm);
        Fx.MxIdent(cx, CTlm);
        Fx.MxIdent(cx, CM);
        return 0;
    }
    public static int PcPage(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells pg, int pi, int page, emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells pa, emon.Port.Cells im, emon.Port.Cells pts, emon.Port.Cells gx) {
        // Interpret page index pi of the page table pg (page number `page`, 1-based, is
        // what the evidence records): its content streams, then the words and lines.
        // Answers 0, or 7 (`need-bytes`) when the source missed: then nothing written is
        // to be used and the caller re-runs on a fresh view (D075).
        int con = Pdfdoc.PdPgContents(pg, pi);
        int g0 = Evidence.GlCount(gl);
        int w0 = Evidence.WdCount(wd);
        int p0 = Evidence.PaCount(pa);
        int i0 = Evidence.ImCount(im);
        int rot = Pdfdoc.PdPgRotate(pg, pi);
        int cw = Pdfdoc.PdPgCrop(pg, pi, 2) - Pdfdoc.PdPgCrop(pg, pi, 0);
        int ch = Pdfdoc.PdPgCrop(pg, pi, 3) - Pdfdoc.PdPgCrop(pg, pi, 1);
        int el = 0;
        int eh = 0;
        int endcs = 0;
        PcBeginPage(cx, page);
        emon.Port.CellsSet(cx, CPts0, Evidence.PtCount(pts));
        PcBaseMatrix(cx, Pdfdoc.PdPgCrop(pg, pi, 0), Pdfdoc.PdPgCrop(pg, pi, 1), Pdfdoc.PdPgCrop(pg, pi, 2), Pdfdoc.PdPgCrop(pg, pi, 3), Pdfdoc.PdPgRotate(pg, pi));
        PcGsReset(cx);
        Pdfgfx.GxPage(gx);
        Pdfgfx.GxOcRead(src, ar, dc, a, b, st, gx);
        if ((rot == 90) || (rot == 270)) {
            emon.Port.CellsSet(cx, CPw, ch);
            emon.Port.CellsSet(cx, CPh, cw);
        } else {
            emon.Port.CellsSet(cx, CPw, cw);
            emon.Port.CellsSet(cx, CPh, ch);
        }
        PcPathReset(cx, pts);
        emon.Port.CellsSet(cx, CRes, Pdfdoc.PdPgResources(pg, pi));
        emon.Port.CellsDrop(cs, 0);
        if (con != 0) {
            if (Pdflex.PlKindOf(ar, con) == 8) {
                PcAppendStream(src, ar, dc, a, b, st, cx, @out, cs, con);
            }
            if (Pdflex.PlKindOf(ar, con) == 6) {
                el = Pdflex.PlFirst(ar, con);
                while ((el != 0) && (emon.Port.CellsAt(cx, CAbort) == 0)) {
                    eh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
                    if (Pdfsrc.PsMissed(src)) {
                        emon.Port.CellsSet(cx, CAbort, 1);
                    }
                    if ((eh != 0) && (Pdflex.PlKindOf(ar, eh) == 8)) {
                        PcAppendStream(src, ar, dc, a, b, st, cx, @out, cs, eh);
                    }
                    el = Pdflex.PlNext(ar, el);
                }
            }
        }
        if (emon.Port.CellsAt(cx, CAbort) == 1) {
            return 7;
        }
        endcs = emon.Port.CellsLen(cs);
        PcRun(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, 0, endcs);
        if (emon.Port.CellsAt(cx, CAbort) == 1) {
            return 7;
        }
        if (Pdfsrc.PsMissed(src)) {
            return 7;
        }
        // The path in progress when the page ended never painted: its points are dropped.
        emon.Port.CellsDrop(pts, emon.Port.CellsAt(cx, CPpts) * 3);
        Pdfvis.PvPage(gl, mk, pa, im, emon.Port.CellsAt(cx, CPw), emon.Port.CellsAt(cx, CPh), g0, p0, i0);
        PcGroup(gl, et, wd, ln, fnt, page, g0, w0);
        return 0;
    }
    public static int PcDocument(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells pg, emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells pa, emon.Port.Cells im, emon.Port.Cells pts, emon.Port.Cells gx) {
        // Every page of an opened document (`pd-open` has answered 0): clears `cx`,
        // then `pc-page` for each page. Answers 0, or 7 when the source missed.
        PcInit(cx, ox);
        emon.Port.CellsDrop(fnt, 0);
        emon.Port.CellsDrop(gx, 0);
        int n = Pdfdoc.PdPages(src, ar, dc, a, b, st, pg);
        int i = 0;
        int status = 0;
        if (n < 0) {
            return 7;
        }
        while (i < n) {
            status = PcPage(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, i, i + 1, wd, ln, pa, im, pts, gx);
            if (status == 7) {
                return 7;
            }
            i += 1;
        }
        return 0;
    }
}
